#!/usr/bin/env python3
"""Original MIT SH-2 gradation diagnostic; adjacent LICENSE.

ST-058-R2 §12.2/figure12.4 and 1997 HTML §12.1 blur controls.
Guest writes both bitmaps, palette and color controls through real MMIO.
"""
import argparse
import hashlib
from pathlib import Path
import struct
from build_effects import assembler, store

HERE = Path(__file__).resolve().parent


def build():
    source = '; Original MIT gradation guest. Generated by build_gradation.py.\n'
    for off, value in [(0x10,0x4FFF),(0x12,0xEEEE),(0x18,0x5555),(0x1A,0xEEEE),
                       (0x20, 3), (0x28, 0x3202), (0x3C, 0x20),
                       (0xF8, 0x403), (0xEC, 0xA003), (0x108, 0x0F0F),
                       (0xE8, 3), (0x10E, 15),
                       (0x78, 1), (0x7C, 1), (0x88, 1), (0x8C, 1)]:
        source += store(0x25F80000 + off, value)
    source += store(0x25F800A8, 0x30000, 'l')
    source += store(0x25E60000, 5)
    for y in range(2):
        source += store(0x25E00000 + y * 256, 0x12341234, 'l')
        for x in range(4, 8):
            source += store(0x25E40000 + (y * 512 + x) * 2, 0xFFFF)
    for index, value in enumerate([0x1F, 0x3E0, 0x7C00, 0x7FFF, 0x3E0], 1):
        source += store(0x25F00000 + index * 2, value)
    source += store(0x25F80000, 0x8000)
    source += store(0x0600A400, 0x600D, 'l') + 'park:\nsleep\nbra park\nnop\n'
    code = assembler.assemble(source, base=0x200)
    assert len(code) < 0x10000
    rom = bytearray(524288)
    rom[:8] = struct.pack('>II', 0x200, 0x06100000)
    rom[0x200:0x200+len(code)] = code
    lines = ['# Original MIT gradation BIOS fixture. Adjacent LICENSE.',
             '# Generated from gradation.s by build_gradation.py; unspecified bytes zero.']
    for at in range(0, len(rom), 16):
        chunk = rom[at:at+16]
        if any(chunk):
            lines.append(f'{at:04X} ' + ' '.join(f'{w:04X}' for w in struct.unpack('>8H', chunk)))
    return source, '\n'.join(lines)+'\n', hashlib.sha256(rom).hexdigest()


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    source, text, digest = build()
    for path, value in [(HERE/'gradation.s', source), (HERE/'gradation.hex', text)]:
        if args.check:
            assert path.read_text() == value, f'Rebuild {path.name}'
        else:
            path.write_text(value)
    print(f'{"Verified" if args.check else "Built"} gradation.hex; expanded ROM SHA-256 {digest}')
